use std::collections::HashSet;

/// Returns a new vector with duplicates removed.
/// Postconditions (informal):
/// 1) `res` contains no duplicates.
/// 2) The set of elements in `res` equals the set of elements in `nums`.
///
/// Note: Order is preserved as “first occurrence wins”.
pub fn remove_duplicates(nums: Vec<i32>) -> Vec<i32> {
    let mut seen: HashSet<i32> = HashSet::new();
    let mut res: Vec<i32> = Vec::new();

    for x in nums {
        if seen.insert(x) {
            // `insert` returns true iff `x` was not present before.
            res.push(x);
        }
    }

    res
}

